SELECT c.id,c.content_type,c.status,a.current_revision_sequence,count(r.id) AS revisions,array_agg(r.reason ORDER BY r.sequence) AS reasons,bool_and(jsonb_typeof(r.document::jsonb->'document'->'root'->'children'->3->'value')='string') AS reference_ids_only FROM content c JOIN article_family_content a ON a.content_id=c.id JOIN revision_records r ON r.article_id=a.id WHERE c.id IN ('a469846d-7726-4f84-bea8-6662b525aee3','03add6d8-f36b-4ef3-9a5d-03ea02b3a876','f141e6a7-37b6-485c-a3de-d9dc12776622') GROUP BY c.id,c.content_type,c.status,a.current_revision_sequence ORDER BY c.content_type,c.id;
